#include <vector>
#include <cstddef>
#include <omp.h>

/* Compute the highest node degree in the undirected graph.
   The graph is defined by the adjacency matrix A stored in row‑major order.
   A is an NxN matrix, N is the number of vertices.
   The function works correctly for any number of OpenMP threads. */
int maxDegree(const std::vector<int>& A, std::size_t N)
{
    int maxDeg = 0;                                   // global maximum (reduced)
#pragma omp parallel for reduction(max:maxDeg) schedule(static)
    for (std::size_t i = 0; i < N; ++i) {
        int deg = 0;
        std::size_t rowStart = i * N;
        for (std::size_t j = 0; j < N; ++j) {
            deg += A[rowStart + j];                  // sum of the i‑th row
        }
        if (deg > maxDeg) {
            maxDeg = deg;                             // reduction handles the race
        }
    }
    return maxDeg;
}
